/* DEC-207 (Bob's D9, K3060: the signing ceremony "based on principles"; Q4): signing happens inside the ceremony, never on a
   separate page or by pasting a signature back. Principles 1.5 and 1.6 (only the member signs, as who they signed in as),
   4.2 and 4.4 (the heaviest act, the fullest friction), 4.5 (it says it is outward at the act), 8.6 (it finishes on a larger
   screen), 9.3 (the group publishes; its member signs). One choice of when, one button that signs and publishes; the
   password asked again (D3); then the member's own device confirms the use of a key that never leaves it (K509 (2)). */
const CER_ST = { device: 'b', signedat: 'c', signednow: 'd', nokey: 'e', phone: 'f', notowner: 'g' };
const cerSteps = cur => `<ol class="mk-steps">${['What', 'Strength', 'Leaves out', 'People', 'Photos', 'Disclosures', 'Bias', 'Preview', 'Ties', 'Sign'].map((t, i) => `<li${i < cur ? ' class="done"' : ''}${i === cur ? ' aria-current="step"' : ''}>${t}</li>`).join('')}</ol>`;
SCR.ceremony = c => { const st = CER_ST[c.v] || 'a'; const sel = v => v === st ? ' selected' : ''; return { rail: 'projects', title: 'Publish', crumbs: ['The Coliseum lease', 'Publish Edition 3'], st, main: `
  <div class="mk-mockctl"><label for="mk-cst">In this mockup, show</label> <select id="mk-cst" class="cs-input" onchange="this.closest('main').dataset.st=this.value"><option value="a"${sel('a')}>the ceremony, at its last steps</option><option value="b"${sel('b')}>your device confirms the signature</option><option value="c"${sel('c')}>signed, publishing at the set time</option><option value="d"${sel('d')}>signed and published now</option><option value="e"${sel('e')}>no signing key in this browser</option><option value="f"${sel('f')}>on a phone</option><option value="g"${sel('g')}>a member who isn't an owner</option></select></div>
  ${h1('Publish Edition 3', 'Publishing makes this edition permanent and public. It can be corrected by a new edition, never removed.')}
  <div class="st st-a">${cerSteps(8)}
  ${sec('Before publishing', sheet(row(I('finding'), 'Finding 1 · meets the bar', strength('B', 'B', '<b>Meets the bar</b> · B/B')) + row(I('finding'), 'Finding 2 · meets the bar', strength('B', 'B', '<b>Meets the bar</b>'))) + acts(btn('publishpreflight', 'Check again')))}
  ${sec('Disclosed with the case', sheet(row(I('tension'), 'An unresolved contradiction: two documents date the rent notice differently', '<span class="muted">disclosed, not blocking</span>') + row(I('timeline'), 'The timeline, frozen at signing (9 events)', '')) + acts(btn('publishtensions', 'See everything that will be disclosed')))}
  ${sec('Photos in this case', `${sheet(row(I('camera'), '<b>Photo · Coliseum parking lot, east gate</b><span class="meta">taken by Dev, 4 September 2026 · relied on by finding 1 · <b>2 areas marked</b>: a passer-by, a car\'s number plate</span>', '<span class="cs-due" data-due="met">' + I('accepted') + 'Marked</span>') + row(I('camera'), '<b>Photo · rent notice on the leasing office door</b><span class="meta">taken by Mai, 2 April 2024 · relied on by finding 2 · nobody in it</span>', '<span class="muted">nothing to obscure</span>'))}${note('Mark anyone in a photo who is not part of a finding, and any number plate. The public copy shows those areas obscured, labeled “Faces, plates and camera details removed for publication; the group holds the original”, and the original stays inside the group. Every photo a published case carries goes out without its camera details (where and when it was taken, and on which device), labeled “Camera details removed for publication; the group holds the original”. City staff at work are part of what the case is about; obscure one only with a reason.')}${note('Every photo the case carries must be checked before signing, including one that only supports a finding: marked, or “nothing to obscure”. A mark that covers the wrong thing is withdrawn with a reason, never erased. Text read from a photo, such as a number plate, is never published with it; a passage you quote in the case still is.')}${acts(btn('obscuremark', 'Mark who and what to obscure'), btn('obscuremarkwithdraw', 'Withdraw a mark, with a reason'))}<p class="mk-small muted" style="margin:0">A photo in a format whose areas can\'t be covered (some phones save HEIC or progressive JPEG) stops the signing, naming the photo: capture it again as an ordinary photo, or stop relying on it. If a mark changes after the case is prepared, prepare it again before signing; if it changes after signing, the case isn\'t published until it is prepared and signed again. Any member who can see a photo may mark it or withdraw a mark; only a member can, never the machine.</p>`)}
  ${sec('Your ties', `${checks('', [['I have no undeclared tie to anyone this case concerns, including anyone paid in its money', true]], { act: 'publish' })}${acts(btn('publish', 'Confirm, and prepare Edition 3 for signing', { help: 'Records your confirmation inside the edition you are about to sign and fixes its text, so what you sign next is exactly what was checked. It publishes nothing.' }))}${note('The member who signs confirms this for themselves, and the confirmation is part of what they sign.')}`)}
  <div class="cs-dialog" style="max-width:none;box-shadow:none"><b>${I('outward')} Sign and publish Edition 3</b>
   <div class="ends">You sign as Dev, an owner of The Coliseum lease. The public page will read “Published by Lakeshore Tenants · signed by Dev”. Once public, anyone can read it and check your signature without asking the group; it can be corrected by a new edition, never removed.</div>
   ${checks('When it becomes public', [['Now', false], ['At a set time: Thursday 19 November 2026, 6:00 (Oakland time)', true]], { radio: true, act: 'publishat' })}
   <p class="mk-note">Until then the signed edition waits, not public. At 6:00 Civicsmith checks again; if anything changed since you signed (a source, a member's confirmation of their ties, a hold), it does not publish and tells you once. You can cancel or move the time until then.</p>
   ${field('mk-cpw', 'Your password', '', { act: 'caseratify', help: 'For this, enter your password again: signing or publishing a case, changing administrators and connecting Claude always ask.' })}
   <p class="mk-small" style="margin:0"><b>One confirmation signs all 8</b>: the edition, its 2 findings, and the 5 pieces of evidence they rest on. Each signature can be checked on its own, so a reader can trust one finding without trusting the rest.</p>
   <details class="mk-details"><summary>What your key signs, exactly</summary><ul class="mk-list mk-small"><li><span class="id">bio-ratify-case CASE-2026-0012 3 3b9f…c210</span> · Edition 3 of The Coliseum lease</li><li><span class="id">bio-ratify FND-2026-0031 7d0e…91ab</span> · Finding 1</li><li><span class="id">bio-ratify FND-2026-0032 c41a…0f57</span> · Finding 2</li><li>5 lines like these, one for each piece of evidence the two findings rest on: the council minutes, lease amendment 1, the rent schedules, and the two photos</li></ul><p class="mk-small muted" style="margin:0">Each line names one thing and the fingerprint of its exact text. If anything in it changes before you sign, you are asked to sign again.</p></details>
   ${acts(btn('publishat', 'Sign and publish at 6:00 on 19 November', { tone: 'primary', icon: 'signed' }), btn('caseratify', 'Sign and publish now', { icon: 'signed' }))}
   <p class="mk-small muted" style="margin:0">Next, your device asks you once to confirm with your signing key. Nothing is signed until you do.</p></div></div>
  <div class="st st-b">${cerSteps(9)}<div class="cs-dialog" style="max-width:none;box-shadow:none"><b>Confirm on your device</b>
   <div class="ends">Your device is asking you to confirm with your signing key: its own window asks for your passphrase, fingerprint or device PIN. The key never leaves this device, and Civicsmith never sees it.</div>
   <div class="mk-osprompt" role="img" aria-label="Your device's own window, drawn as an example"><span class="mk-small muted">Your device's own window (it looks different on each device)</span><b>Use your signing key?</b><span>Civicsmith at lakeshore-tenants wants to sign 8 statements: Edition 3 of The Coliseum lease, its 2 findings and their 5 pieces of evidence.</span><span class="mk-small">Touch the sensor, or enter your device PIN</span></div>
   <p class="mk-small muted" style="margin:0">If you cancel there, or your device doesn't confirm, nothing is signed or published, and you are back at the last step with everything as it was.</p></div></div>
  <div class="st st-c">${cerSteps(10)}${row(I('signed'), '<b>Signed. Edition 3 becomes public on Thursday 19 November at 6:00 (Oakland time).</b> Until then it waits, not public. At 6:00 Civicsmith checks again and publishes only if nothing changed since you signed.', '')}${sheet(row(I('accepted'), 'Edition 3', '<span class="muted">signed</span>') + row(I('accepted'), 'Findings 1 and 2', '<span class="muted">signed</span>') + row(I('accepted'), 'The 5 pieces of evidence', '<span class="muted">signed</span>'))}
   ${acts(btn('publishatmove', 'Move the time'), btn('publishatcancel', 'Cancel publishing'))}
   ${note('The case page and your queue show this until it goes public; then your queue tells you once that it is live. The public page shows when it was signed and when it was published.')}</div>
  <div class="st st-d">${cerSteps(10)}${row(I('accepted'), '<b>Signed and published.</b> Edition 3 is public now: anyone can read it and check your signature without the group. Members who follow this case are told once.', '')}
   ${acts(ref(I('case') + 'Open the public page', 'published', '<b>Edition 3</b> · as any reader sees it'))}</div>
  <div class="st st-e">${cerSteps(9)}<div class="cs-dialog" style="max-width:none;box-shadow:none"><b>You have no signing key in this browser</b>
   <div class="ends">Register one here. It is made on this device and can never be copied out of it; every use asks you to confirm. Unless you keep it on this device, you save it as a key file, protected by a passphrase you choose. Then you come back to this step, with nothing lost.</div>
   ${checks('', [['Keep this key on this device, so you can sign here again without loading it. Leave this unticked on a computer others use: you then load your key file each time you sign.', false]], { act: 'signerregisterown' })}
   ${acts(btn('signerregisterown', 'Register a signing key in this browser', { tone: 'primary', help: 'Makes your signing key on this device and registers its public half with your group, so readers can check what you sign. The key itself never leaves this device.' }))}
   ${acts('<button type="button" class="cs-btn" data-tone="quiet">Use a key file you already have</button>')}
   <p class="mk-small muted" style="margin:0">Registered a key on another computer? Sign from that one, or register a key here too. Lost a key? Withdraw it under Settings › Your account and make a new one here; cases it already signed can still be checked. Your signing keys are listed there.</p></div></div>
  <div class="st st-f">${cerSteps(9)}${row(I('status'), '<b>Signing and publishing finish on a larger screen.</b> Everything here can be read on a phone. Open The Coliseum lease on a computer to sign: the ceremony is where you left it, with every check you made.', '')}</div>
  <div class="st st-g">${cerSteps(9)}${row(I('subject'), '<b>Only an owner of The Coliseum lease signs its cases: Dev and Rosa.</b> Everything you prepared stays as it is. Ask one of them to sign; they see it ready in their queue.', '')}
   ${acts(btn('signrequest', 'Ask an owner to sign', { help: 'Tells Dev and Rosa, in their queues, that Edition 3 is prepared and ready to sign. It signs nothing; either of them goes through the last steps and signs.' }))}</div>` }; };

SCR.published = c => ({ frame: 'published', title: 'The Coliseum lease · Edition 2', main: `
  <div class="mk-pubtitle"><h1 class="rec">The Coliseum lease</h1><p>Edition 2 · published 18 September 2026 · <a href="#" onclick="return false">Edition 1</a></p></div>
  <p class="mk-explain">This case is the work of Lakeshore Tenants. Each finding shows two strengths: how well its documents are held, and how firmly they are linked. <a href="#" onclick="return false">How to read a case</a></p>
  <article class="mk-finding"><span class="eyebrow">Finding 1</span><p class="rec mk-fbody">We found that the 2024 rent adjustments were made without the council vote the lease requires.</p><p>Relied on · meets this project's bar (capture B, connection B) · <a href="#" onclick="return false">the evidence</a></p></article>
  <article class="mk-finding"><span class="eyebrow">Timeline</span><div class="mk-lanes small"><div class="mk-lanehead">What they did</div><div class="mk-lanehead">What we did</div><div class="mk-ev"><span class="mk-date">12 Jan 2024</span>Council approves amendment 1</div><div></div><div class="mk-ev"><span class="mk-date">March 2024</span>Rent adjusted, signed by the City Administrator</div><div></div><div></div><div class="mk-ev us"><span class="mk-date">4 Sep 2026</span>We requested the schedules</div></div></article>
  <article class="mk-finding"><span class="eyebrow">People named</span><p>The City Administrator, by title: signed the March 2024 adjustment (finding 1).</p></article>
  ${acts(btn('verify', 'Check the signature'), btn('publishedcase', 'Download the complete edition'))}
  ${sec('Check a file you hold', `${field('mk-sha', 'Its SHA-256', '9f2c41e0…', { help: 'The file\'s fingerprint: a 64-character code your computer can work out from the file. Paste it here; the file itself never leaves your computer.' })}${acts(btn('verify', 'Check it'))}<p class="mk-small">${I('accepted')}<b>This edition holds it:</b> the evidence for finding 2, “The shortfall was not reported to council”.</p><p class="mk-small muted">Or: “This edition holds no file with that fingerprint.” It may be a different copy, or not part of this case.</p>`, { help: 'Anyone can check whether a file they were given is one this case rests on, without asking the group.' })}` });

// DEC-236 (B204 (2), N1087): the list of imported cases (case-import R4, `importedcases`) as states b and c; the case itself is state a.
SCR.imported = c => { const st = ({ list: 'b', none: 'c' })[c.v] || 'a'; const sel = v => v === st ? ' selected' : ''; return { rail: 'projects', title: st === 'a' ? 'Another group\'s case' : 'Imported cases', st, band: st === 'a' ? 'imported' : undefined, crumbs: st === 'a' ? ['Imported cases', 'West Oakland Neighbors · Port lease revenue'] : ['Projects', 'Imported cases'], main: `
  <div class="mk-mockctl"><label for="mk-impst">In this mockup, show</label> <select id="mk-impst" class="cs-input" onchange="this.closest('main').dataset.st=this.value"><option value="a"${sel('a')}>one imported case</option><option value="b"${sel('b')}>the list of imported cases</option><option value="c"${sel('c')}>the list, before any import</option></select></div>
  <div class="st st-b">
  ${h1('Imported cases', 'Cases other groups published that your group brought in to check. Each opens read-only, recreated finding by finding.')}
  ${sheet(row(I('case'), ref('Port lease revenue', 'imported', '<b>Port lease revenue</b> · West Oakland Neighbors · Edition 2'), '', 'West Oakland Neighbors · Edition 2 · imported by Dev, 1 October · 1 of 3 findings recreated, 1 in part') + row(I('case'), ref('School bus contracts', 'imported', '<b>School bus contracts</b> · Fruitvale Parents · Edition 1'), '', 'Fruitvale Parents · Edition 1 · imported by Ana, 22 September · 4 of 4 findings recreated'))}
  ${acts(btn('caseimport', 'Import a case', { tone: 'primary' }))}
  </div>
  <div class="st st-c">
  ${h1('Imported cases', 'Cases other groups published that your group brought in to check. Each opens read-only, recreated finding by finding.')}
  ${note('No case imported yet. Choose a case file to import the first.')}
  ${acts(btn('caseimport', 'Import a case', { tone: 'primary' }))}
  </div>
  <div class="st st-a">
  ${h1('Port lease revenue', 'West Oakland Neighbors · Edition 2 · imported by Dev, 1 October')}
  ${sheet(row(I('finding'), '<span class="rec">Port lease revenue fell short of the adopted budget in three years</span>', `<span class="cs-recreate" data-r="yes">${I('accepted')}Recreated</span>`) +
    row(I('finding'), '<span class="rec">The shortfall was not reported to council</span>', `<span class="cs-recreate" data-r="part">${I('elsewhere')}Recreated in part</span>`) +
    row(I('finding'), '<span class="rec">The 2025 calculation of arrears</span>', `<span class="cs-recreate" data-r="no">${I('refused')}Did not recreate</span>`))}
  ${acts(btn('caseimport', 'Import a case'), btn('importaccept', 'Accept what recreated, with a reason', { tone: 'primary' }), btn('importflag', 'Flag an issue'), btn('importwatch', 'Watch the publisher\'s docket'))}
  </div>` }; };

SCR.docket = c => ({ rail: 'projects', title: 'Docket', crumbs: ['The Coliseum lease', 'Docket'], main: `
  ${h1('Docket', 'The case\'s public record of corrections, withdrawals and orders.')}
  ${sheet(row(I('signed'), '<b>18 September 2026</b> · Edition 2 published, superseding Edition 1', '') + row(I('case'), '<b>Draft</b> · Order of 2 October, Superior Court: seal exhibit 4 (a tenant\'s address)', '<span class="muted">captured · not yet posted</span>'))}
  ${acts(btn('docketfile', 'File a docket entry'), btn('docketpost', 'Post it, signed', { tone: 'primary' }))}
  ${note('An order is complied with openly: the next edition is stamped with what was sealed and why.')}` });

/* ---------------- outside the group ---------------- */
SCR.inbox = c => ({ rail: 'queue', title: 'Inbox', crumbs: ['Inbox'], main: `
  ${h1('Inbox', 'Material handed in through your doorbell.')}
  ${sheet(row(I('capture'), '<b>3 PDFs</b> · "These are the inspection sheets they don\'t publish." <span class="meta"><span class="id">KNOCK-2026-10-03-9c1f</span> · same knocker as 12 September</span>', ''))}
  ${ladder('ident', ['Unknown', 'Same knocker', 'Partly known', 'Known to the group', 'Public'], 2)}
  ${acts(btn('inboxpull', 'Move into the record', { tone: 'primary' }), btn('inboxresolve', 'Discard, with a reason'), btn('sourcelink', 'Record what is known of the source'))}` });

SCR.doorbell = c => ({ frame: 'public', title: 'Hand material to Lakeshore Tenants', main: `
  <div class="mk-setuphead"><span class="grp mk-grp">Lakeshore Tenants</span></div>
  ${h1('Hand material to Lakeshore Tenants', 'You don\'t need an account. Here is exactly what happens to what you send.')}
  <ul class="mk-list"><li>Your files go only to this group's own Civicsmith.</li><li>A member reads them and decides whether to use them.</li><li>You can add a secret phrase, so later material can be recognized as yours without anyone knowing who you are.</li><li>Nothing here is beyond a court's reach. <a href="#" onclick="return false">What that means</a></li></ul>
  <div class="mk-drop">${I('add')} Choose files</div>
  ${field('mk-kn', 'A note (optional)', 'These are the inspection sheets they don\'t publish.', { area: true })}
  ${field('mk-ks', 'A secret phrase (optional)', '')}
  ${acts(btn('knock', 'Hand it over', { tone: 'primary' }))}` });
